# صفحه‌بندی متفاوت برای اکشن خاص
class BookViewSet(viewsets.ModelViewSet):
    queryset = Book.objects.all()
    serializer_class = BookSerializer
    pagination_class = StandardPagination

    @action(detail=False, methods=["get"], pagination_class=None)
    def all(self, request):
        # این اکشن بدون صفحه‌بندی
        books = self.get_queryset()
        return Response(self.get_serializer(books, many=True).data)


# صفحه‌بندی پویا
class ProductViewSet(viewsets.ModelViewSet):
    queryset = Product.objects.all()
    serializer_class = ProductSerializer

    def get_paginator(self):
        if self.request.query_params.get("cursor"):
            return CursorPagination()
        return StandardPagination()

    @property
    def paginator(self):
        if not hasattr(self, "_paginator"):
            self._paginator = self.get_paginator()
        return self._paginator

class BookListView(APIView):
    pagination_class = StandardPagination

    @property
    def paginator(self):
        if not hasattr(self, "_paginator"):
            self._paginator = self.pagination_class()
        return self._paginator

    def get(self, request):
        books = Book.objects.all()
        page = self.paginator.paginate_queryset(books, request, view=self)
        if page is not None:
            serializer = BookSerializer(page, many=True)
            return self.paginator.get_paginated_response(serializer.data)
        serializer = BookSerializer(books, many=True)
        return Response(serializer.data)

class OptimizedPagination(PageNumberPagination):
    page_size = 20
    max_page_size = 100

    def get_paginated_response(self, data):
        # برای count گران، می‌توانید حذف کنید
        # اما کلاینت نیاز دارد معمولاً
        return super().get_paginated_response(data)
